/* ============================================================
 * 25-transclusion.js
 * Native page, block, and section transclusion.
 *
 * Syntax (primary):
 *   ![[Page Title]]            — transclude a whole page
 *   !((block-id))              — transclude one block + its children
 *   ![[Page Title#Heading]]    — transclude a heading section
 *
 * Also accepts explicit forms when pasted/generated by integrations:
 *   {{transclude:page|Page Title}}
 *   {{transclude:block|block-id}}
 *   {{transclude:section|Page Title#Heading}}
 *
 * Transclusions are live: every render reads the source state directly.
 * A depth/cycle guard prevents recursive embeds from exhausting the DOM.
 * ============================================================ */
"use strict";

var NEXUS_TRANSCLUSION_MAX_DEPTH = 4;
var NEXUS_TRANSCLUSION_PATTERN = /!\[\[([^\]]+)\]\]|!\(\(([a-zA-Z0-9_-]+)\)\)|\{\{transclude:(page|block|section)\|([^}]+)\}\)|\[\[([^\]]+)\]\]|#([a-zA-Z0-9_][\w-]*)|\(\(([a-zA-Z0-9_-]+)\)\)|\*\*([^*]+)\*\*|~~([^~]+)~~|`([^`]+)`|\*([^*\s][^*]*)\*|\{\{img:([a-zA-Z0-9_-]+\|[^}]*)\}\}|\{\{file:([a-zA-Z0-9_-]+\|[^}]*)\}\}|\{\{mark:([a-z]+)\|([^}]*)\}\}|%%color:([a-z]+)\|([^%]*)%%/g;

/* Replace the shared inline parser after 00-state-and-helpers.js has
   established it. Every consumer already creates a fresh RegExp from
   INLINE_PATTERN, so changing this one shared reference is enough. */
INLINE_PATTERN = NEXUS_TRANSCLUSION_PATTERN;

var nexusTransclusionStack = [];

function transclusionSourceKey(type, target){
  return type + ':' + String(target || '').toLowerCase();
}
function transclusionEscapeText(value){ return escapeHtml(String(value == null ? '' : value)); }

function parseTransclusionTarget(raw, fallbackPageId){
  var text = String(raw || '').trim();
  var page = null, heading = null;
  var hash = text.indexOf('#');
  if(hash >= 0){
    heading = text.slice(hash + 1).trim();
    page = text.slice(0, hash).trim();
  }else page = text;
  if(!page && fallbackPageId && state.pages[fallbackPageId]) page = state.pages[fallbackPageId].title;
  return {page:page, heading:heading};
}

function transclusionDocumentRows(page){
  var out = [];
  if(!page) return out;
  function walk(ids, depth){
    (ids || []).forEach(function(id){
      var b = state.blocks[id];
      if(!b) return;
      out.push({block:b, depth:depth});
      if(b.children && b.children.length) walk(b.children, depth + 1);
    });
  }
  walk(page.rootBlocks || [], 0);
  return out;
}

function findTransclusionSection(page, headingText){
  var wanted = String(headingText || '').trim().toLowerCase();
  if(!page || !wanted) return [];
  var rows = transclusionDocumentRows(page);
  var start = -1, startInfo = null;
  for(var i=0;i<rows.length;i++){
    var hi = headingInfo(rows[i].block.text || '');
    if(hi && hi.rest.trim().toLowerCase() === wanted){ start = i; startInfo = {level:hi.level, depth:rows[i].depth}; break; }
  }
  if(start < 0) return [];
  var result = [];
  for(var j=start;j<rows.length;j++){
    if(j > start){
      var nextHi = headingInfo(rows[j].block.text || '');
      if(nextHi && nextHi.level <= startInfo.level) break;
    }
    result.push(rows[j]);
  }
  return result;
}

function transclusionCardStart(kind, title, sourceLabel, missing){
  var cls = 'transclusion-card transclusion-' + kind + (missing ? ' transclusion-missing' : '');
  var out = '<span class="' + cls + '" data-transclusion-kind="' + escapeHtml(kind) + '">' +
    '<span class="transclusion-head">' +
      '<span class="transclusion-kind">' + escapeHtml(kind === 'page' ? 'PAGE' : kind === 'section' ? 'SECTION' : 'BLOCK') + '</span>' +
      '<span class="transclusion-title">' + escapeHtml(title || '') + '</span>' +
      (sourceLabel ? '<span class="transclusion-source">' + escapeHtml(sourceLabel) + '</span>' : '') +
    '</span>';
  if(missing) out += '<span class="transclusion-body transclusion-error">' + escapeHtml(title || 'Missing transclusion') + '</span></span>';
  return out;
}

function transclusionBlockRowsHtml(rows, depth, sourcePageId){
  depth = depth || 0;
  var out = '<span class="transclusion-body">';
  rows.forEach(function(item){
    var b = item.block;
    if(!b) return;
    var h = headingInfo(b.text || '');
    var body = h ? '<span class="transclusion-heading level-' + h.level + '">' + decorateText(h.rest, depth + 1) + '</span>' : decorateText(b.text || '', depth + 1);
    out += '<span class="transclusion-line" style="--tx-depth:' + Math.min(8, item.depth || 0) + '">' +
      '<span class="transclusion-bullet">•</span><span class="transclusion-line-content">' + body + '</span></span>';
  });
  out += '</span>';
  return out;
}

function closeTransclusionCard(out){ return out + '</span>'; }

function renderPageTransclusion(page, depth){
  var rows = transclusionDocumentRows(page);
  var key = transclusionSourceKey('page', page.id);
  if(nexusTransclusionStack.indexOf(key) >= 0){
    return transclusionCardStart('page','Circular page transclusion',page.title,true);
  }
  if(depth >= NEXUS_TRANSCLUSION_MAX_DEPTH){
    return transclusionCardStart('page','Transclusion depth limit reached',page.title,true);
  }
  nexusTransclusionStack.push(key);
  var out = transclusionCardStart('page', page.title, page.locked ? 'Locked' : 'Live');
  out += transclusionBlockRowsHtml(rows, depth, page.id);
  nexusTransclusionStack.pop();
  return closeTransclusionCard(out);
}

function renderBlockTransclusion(block, depth){
  var key = transclusionSourceKey('block', block.id);
  var page = state.pages[block.pageId];
  if(nexusTransclusionStack.indexOf(key) >= 0){
    return transclusionCardStart('block','Circular block transclusion',page ? page.title : '',true);
  }
  if(depth >= NEXUS_TRANSCLUSION_MAX_DEPTH){
    return transclusionCardStart('block','Transclusion depth limit reached',page ? page.title : '',true);
  }
  nexusTransclusionStack.push(key);
  var rows = [];
  (function walk(b, d){
    if(!b) return;
    rows.push({block:b, depth:d});
    (b.children||[]).forEach(function(cid){ walk(state.blocks[cid], d + 1); });
  })(block,0);
  var out = transclusionCardStart('block', blockPreviewText(block), page ? page.title : 'Live block');
  out += transclusionBlockRowsHtml(rows, depth, block.pageId);
  nexusTransclusionStack.pop();
  return closeTransclusionCard(out);
}

function renderSectionTransclusion(page, headingText, depth){
  var key = transclusionSourceKey('section', page.id + '#' + headingText);
  var rows = findTransclusionSection(page, headingText);
  if(nexusTransclusionStack.indexOf(key) >= 0){
    return transclusionCardStart('section','Circular section transclusion',page.title,true);
  }
  if(depth >= NEXUS_TRANSCLUSION_MAX_DEPTH){
    return transclusionCardStart('section','Transclusion depth limit reached',page.title,true);
  }
  if(!rows.length){
    return transclusionCardStart('section','Section not found: ' + headingText,page.title,true);
  }
  nexusTransclusionStack.push(key);
  var out = transclusionCardStart('section', headingText, page.title);
  out += transclusionBlockRowsHtml(rows, depth, page.id);
  nexusTransclusionStack.pop();
  return closeTransclusionCard(out);
}

function renderTransclusionHtml(kind, target, depth, fallbackPageId){
  depth = depth || 0;
  var parsed, page, block;
  if(kind === 'block'){
    block = state.blocks[String(target || '').trim()];
    if(!block) return transclusionCardStart('block','Missing block: ' + String(target || ''),'',true);
    return renderBlockTransclusion(block, depth);
  }
  parsed = parseTransclusionTarget(target, fallbackPageId);
  page = parsed.page ? findPageByTitle(parsed.page) : null;
  if(!page){
    return transclusionCardStart(kind, parsed.page || String(target || ''), 'Page not found', true);
  }
  if(kind === 'section' || parsed.heading){ return renderSectionTransclusion(page, parsed.heading || '', depth); }
  return renderPageTransclusion(page, depth);
}

function renderExplicitTransclusion(raw, depth, fallbackPageId){
  var m = String(raw || '').match(/^!\[\[([^\]]+)\]\]$/);
  if(m){
    var parsed = parseTransclusionTarget(m[1], fallbackPageId);
    return parsed.heading ? renderTransclusionHtml('section', m[1], depth, fallbackPageId) : renderTransclusionHtml('page', m[1], depth, fallbackPageId);
  }
  m = String(raw || '').match(/^!\(\(([a-zA-Z0-9_-]+)\)\)$/);
  if(m) return renderTransclusionHtml('block', m[1], depth, fallbackPageId);
  m = String(raw || '').match(/^\{\{transclude:(page|block|section)\|([^}]+)\}\}$/);
  if(m) return renderTransclusionHtml(m[1], m[2], depth, fallbackPageId);
  return escapeHtml(raw || '');
}

function buildTransclusionNode(raw, depth, fallbackPageId){
  var wrap = document.createElement('span');
  wrap.className = 'transclusion';
  wrap.contentEditable = 'false';
  wrap.dataset.transclusionRaw = raw;
  wrap.title = 'Live transclusion — click to open the source';
  wrap.innerHTML = renderExplicitTransclusion(raw, depth || 0, fallbackPageId || state.currentPageId);
  return wrap;
}

/* Add all three transclusion commands to the existing slash command
   catalogue without duplicating its implementation. */
var nexusBaseSlashCommandList = (typeof slashCommandList === 'function') ? slashCommandList : null;
function nexusInsertTransclusionFromSlash(ctx, syntaxPrompt, builder){
  var target = prompt(syntaxPrompt);
  if(target === null) return;
  target = target.trim();
  if(!target) return;
  applyBlockText(ctx.block, ctx.head + builder(target) + ctx.tail, ctx.head.length + builder(target).length);
}
if(nexusBaseSlashCommandList){
  slashCommandList = function(){
    var cmds = nexusBaseSlashCommandList();
    cmds.splice(0,0,
      {icon:'▣', label:'Page transclusion', sub:'Insert', keywords:'embed transclude page live include', run:function(ctx){
        nexusInsertTransclusionFromSlash(ctx, 'Page to transclude:', function(v){ return '![[' + v + ']]'; });
      }},
      {icon:'↳', label:'Block transclusion', sub:'Insert', keywords:'embed transclude block live include reference', run:function(ctx){
        nexusInsertTransclusionFromSlash(ctx, 'Block ID to transclude:', function(v){ return '!((' + v + '))'; });
      }},
      {icon:'§', label:'Section transclusion', sub:'Insert', keywords:'embed transclude section heading subsection live include', run:function(ctx){
        nexusInsertTransclusionFromSlash(ctx, 'Section to transclude (Page#Heading):', function(v){ return '![[' + v + ']]'; });
      }}
    );
    return cmds;
  };
}

